
;/* module: js/r41-release-polish.js */
(function(){
  'use strict';
  const VERSION=60,startedAt=Date.now(),errors=[];
  let settled=false,timer=null;
  const el=id=>document.getElementById(id);
  const describeError=value=>{
    if(!value)return 'Неизвестная ошибка запуска';
    if(value instanceof Error)return value.message||value.name||'Ошибка запуска';
    if(typeof value==='string')return value;
    try{return String(value.message||value.reason||value.type||value);}catch(e){return 'Ошибка запуска';}
  };
  function record(value){if(settled)return;const msg=describeError(value).slice(0,220);if(msg&&!errors.includes(msg))errors.push(msg);if(errors.length>8)errors.shift();}
  window.addEventListener('error',e=>record(e.error||e.message||e),true);
  window.addEventListener('unhandledrejection',e=>record(e.reason||e),true);
  function coreReady(){
    try{
      const shell=typeof r18ValidateUIShell==='function'?r18ValidateUIShell():null;
      const roster=typeof DB!=='undefined'&&Array.isArray(DB)&&DB.length===74;
      const hub=el('command-hub');
      const phase=document.body&&document.body.dataset.r18Phase==='hub';
      const stats=el('hub-stat-fighters');
      return !!(shell&&shell.pass&&roster&&hub&&!hub.classList.contains('hidden')&&phase&&stats&&Number(stats.textContent)===74);
    }catch(e){record(e);return false;}
  }
  function finish(){
    if(settled)return;settled=true;if(timer)clearTimeout(timer);
    const boot=el('app-boot');if(boot){boot.dataset.state='ready';const status=el('app-boot-status');if(status)status.textContent='Арена готова.';setTimeout(()=>boot.remove(),360);}
    if(document.body)document.body.classList.remove('app-booting');
  }
  function fail(){
    if(settled)return;settled=true;if(timer)clearTimeout(timer);
    const boot=el('app-boot'),title=el('app-boot-title'),status=el('app-boot-status'),retry=el('app-boot-retry');
    if(boot)boot.dataset.state='error';
    if(title)title.textContent='НЕ УДАЛОСЬ ЗАПУСТИТЬ ИГРУ';
    if(status)status.textContent='Не удалось подготовить игровой интерфейс. Обновите страницу и попробуйте снова.';
    if(retry){retry.classList.remove('hidden');retry.addEventListener('click',()=>location.reload(),{once:true});}
    if(document.body)document.body.classList.remove('app-booting');
  }
  function tick(){if(coreReady())return finish();if(Date.now()-startedAt>=8000)return fail();timer=setTimeout(tick,120);}
  function start(){const retry=el('app-boot-retry');if(retry)retry.addEventListener('click',()=>location.reload(),{once:true});tick();}
  if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',start,{once:true});else start();
  window.APP_RELEASE_GUARD=Object.freeze({version:VERSION,snapshot:()=>Object.freeze({version:VERSION,ready:settled&&coreReady(),settled,elapsedMs:Date.now()-startedAt,errors:[...errors]})});
})();

