const ROSTER_BY_UID = new Map(DB.map(f => [f.uid, f]));
const ROSTER_BY_LEGACY_ID = new Map(DB.map(f => [f.id, f]));
const ROSTER_BY_NAME = new Map(DB.map(f => [f.name, f]));

function getFighterByUid(uid) { return ROSTER_BY_UID.get(uid) || null; }
function getFighterByLegacyId(id) { return ROSTER_BY_LEGACY_ID.get(Number(id)) || null; }
function getFighterByName(name) { return ROSTER_BY_NAME.get(String(name || '')) || null; }

function validateRosterModel() {
    const errors = [];
    const warnings = [];
    const seenUid = new Set(), seenLegacy = new Set(), seenName = new Set(), seenImg = new Set();
    DB.forEach((f, index) => {
        const expectedUid = `fighter_${String(index + 1).padStart(3, '0')}`;
        if (!Number.isInteger(f.id)) errors.push(`legacy id is not integer: ${f.name}`);
        if (seenLegacy.has(f.id)) errors.push(`duplicate legacy id: ${f.id}`); else seenLegacy.add(f.id);
        if (!f.uid || seenUid.has(f.uid)) errors.push(`missing/duplicate uid: ${f.uid || '(empty)'}`); else seenUid.add(f.uid);
        if (f.uid !== expectedUid) warnings.push(`uid sequence differs at ${f.name}: ${f.uid} != ${expectedUid}`);
        if (!f.name || seenName.has(f.name)) errors.push(`missing/duplicate public name: ${f.name || '(empty)'}`); else seenName.add(f.name);
        if (!f.img || seenImg.has(f.img)) errors.push(`missing/duplicate portrait: ${f.img || '(empty)'}`); else seenImg.add(f.img);
        if (!f.prime || f.prime.mode !== 'FIXED' || f.prime.formKey !== PRIME_FORM_KEY || f.prime.locked !== true) errors.push(`prime invariant failed: ${f.uid}`);
        if (!Array.isArray(f.affiliations) || !f.affiliations.length) errors.push(`no affiliations: ${f.uid}`);
        (f.affiliations || []).forEach(id => { if (!SHINOBI_AFFILIATIONS[id]) errors.push(`unknown affiliation ${id}: ${f.uid}`); });
        if (!Array.isArray(f.archetypes) || f.archetypes.length < 2) errors.push(`too few archetypes: ${f.uid}`);
        (f.archetypes || []).forEach(id => { if (!SHINOBI_ARCHETYPES[id]) errors.push(`unknown archetype ${id}: ${f.uid}`); });
    });
    return { pass: errors.length === 0, schemaVersion: ROSTER_SCHEMA_VERSION, fighters: DB.length, errors, warnings };
}

const ROSTER_VALIDATION = validateRosterModel();
if (ROSTER_VALIDATION.pass) console.log(`✅ R4 roster model validated: ${ROSTER_VALIDATION.fighters} fighters`);
else console.error('❌ R4 roster model validation failed', ROSTER_VALIDATION);

