;/* module: js/database.js */
let MATCHUP_BY_PAIR = new Map();
let MATCHUP_DATABASE_VALIDATION = null;

function matchupPairKey(uidA, uidB) {
    const a=String(uidA||''), b=String(uidB||'');
    if (!a || !b || a === b) return '';
    return a < b ? a+'__'+b : b+'__'+a;
}

function getBaseMatchupByUids(uidA, uidB) {
    const key=matchupPairKey(uidA,uidB);
    return key ? (MATCHUP_BY_PAIR.get(key) || null) : null;
}

function validateMatchupDatabase() {
    const errors=[], warnings=[];
    const data=window.SHINOBI_MATCHUPS_DATA||{};
    const fights=Array.isArray(data.fights)?data.fights:[];
    const fighterUids=new Set(DB.map(f=>f.uid));
    const expected=DB.length*(DB.length-1)/2;
    const ids=new Set(), pairs=new Set();
    if (data.schemaVersion !== 6) errors.push('matchup schemaVersion != 6');
    if (fights.length !== expected) errors.push('matchup count '+fights.length+' != '+expected);
    fights.forEach((m,i)=>{
        if (!m || !m.id) { errors.push('missing matchup row/id at '+i); return; }
        if (ids.has(m.id)) errors.push('duplicate matchup id '+m.id); else ids.add(m.id);
        if (!fighterUids.has(m.fighterAUid)||!fighterUids.has(m.fighterBUid)) errors.push('unknown fighter uid '+m.id);
        if (m.fighterAUid===m.fighterBUid) errors.push('self matchup '+m.id);
        const key=matchupPairKey(m.fighterAUid,m.fighterBUid);
        if (!key) errors.push('invalid pair '+m.id); else if (pairs.has(key)) errors.push('duplicate pair '+key); else pairs.add(key);
        if (m.winnerUid!==m.fighterAUid && m.winnerUid!==m.fighterBUid) errors.push('winner not participant '+m.id);
        if (!['FRESH','WOUNDED','EXHAUSTED','NEAR_DEATH'].includes(m.winnerExitState)) errors.push('invalid winnerExitState '+m.id);
        const severity={FRESH:0,WOUNDED:1,EXHAUSTED:2,NEAR_DEATH:3}[m.winnerExitState];
        if (m.winnerExitSeverity!==severity) errors.push('exit severity mismatch '+m.id);
        if ('comment' in m || 'legacyComment' in m || 'description' in m) errors.push('legacy narrative leaked into runtime '+m.id);
    });
    if (pairs.size!==expected) errors.push('unique pair coverage '+pairs.size+' != '+expected);
    return {pass:errors.length===0,schemaVersion:data.schemaVersion||null,fights:fights.length,uniquePairs:pairs.size,directionalLookupEquivalent:pairs.size*2,errors,warnings};
}

function loadEmbeddedDatabase() {
    const data=window.SHINOBI_MATCHUPS_DATA||{};
    const fights=Array.isArray(data.fights)?data.fights:[];
    MATCHUP_BY_PAIR=new Map();
    fights.forEach(m=>{ const key=matchupPairKey(m.fighterAUid,m.fighterBUid); if(key) MATCHUP_BY_PAIR.set(key,m); });
    MATCHUP_DATABASE_VALIDATION=validateMatchupDatabase();
    if (!MATCHUP_DATABASE_VALIDATION.pass) console.error('❌ R6 matchup database validation failed',MATCHUP_DATABASE_VALIDATION);
    else console.log('✅ R6 UID matchup database: '+MATCHUP_DATABASE_VALIDATION.uniquePairs+' unique / '+MATCHUP_DATABASE_VALIDATION.directionalLookupEquivalent+' directed lookups');
    return MATCHUP_DATABASE_VALIDATION;
}

