function attachOrDetachScroll(charIndex) {
    const team = currentScrollPlayer === 1 ? p1Team : p2Team;
    const inventory = currentScrollPlayer === 1 ? p1ScrollsInventory : p2ScrollsInventory;
    const char = team[charIndex];
    if (!char) return;
    const leader=globalThis.COMPOSITE_CARDS?.getLeaderForFighter?.(team,currentScrollPlayer,char.uid)||char;
    if(leader.uid!==char.uid)return;

    if (char.scroll) {
        const detached = ensureScrollInstance(char.scroll,char.uid);
        detached.ownerUid = null;
        inventory.push(detached);
        char.scroll = null;
        selectedInventoryScrollIndex = null;
        playSwordSound();
    } else if (selectedInventoryScrollIndex !== null && inventory[selectedInventoryScrollIndex]) {
        if (getEquippedScrollCount(team) >= getScrollDrawPolicy(currentScrollPlayer).maxEquipped) return;
        const selected = inventory.splice(selectedInventoryScrollIndex,1)[0];
        char.scroll = ensureScrollInstance(selected,char.uid);
        char.scroll.ownerUid = char.uid;
        selectedInventoryScrollIndex = null;
        playChakraBurst();
    }
    renderScrollPhaseUI();
}

function nextScrollTurn() {
    const team = currentScrollPlayer === 1 ? p1Team : p2Team;
    if (getEquippedScrollCount(team) > getScrollDrawPolicy(currentScrollPlayer).maxEquipped) { renderScrollPhaseUI(); return; }
    scrollTurnsCount++;
    if (scrollTurnsCount < 2) {
        currentScrollPlayer = currentScrollPlayer === 1 ? 2 : 1;
        setupScrollTurn();
    } else {
        startArenaPhaseR61();
    }
}

