    Object.freeze({id:'draft',nodeId:'draft-phase',label:'Драфт',status:'Тактический драфт 5×5',focus:'#draft-keep-btn,#draft-pass-btn'}),
    Object.freeze({id:'scroll',nodeId:'scroll-phase',label:'Подготовка',status:'Подготовка после драфта',focus:'#roll-scrolls-btn,#confirm-scroll-btn'}),
    Object.freeze({id:'arena',nodeId:'arena-phase',label:'Арена',status:'Прокрутка арены',focus:'#roll-arena-btn,#enter-battle-btn'}),
    Object.freeze({id:'battle',nodeId:'battle-phase',label:'Бой',status:'Боевой стол',focus:'#fight-btn'}),
    Object.freeze({id:'end',nodeId:'end-screen',label:'Итог',status:'Итоги матча',focus:'#end-action-btn'})
