    ['startScrollPhase','setupScrollTurn','rollScrolls','attachOrDetachScroll','nextScrollTurn'].forEach(name=>patch(name,(orig,args)=>{const out=orig.apply(this,args);setTimeout(()=>phase()==='arena'?guideArena():phase()==='battle'?guideBattle():guideScroll(),40);return out;}));
